import type { ComponentProps, JSX } from '@solidjs/web'
import {
  createListboxController,
  Listbox as UiListbox,
  ListboxGroup as UiListboxGroup,
  ListboxGroupLabel as UiListboxGroupLabel,
  ListboxItem as UiListboxItem,
  ListboxItemIcon as UiListboxItemIcon,
  ListboxItemIndicator as UiListboxItemIndicator,
  ListboxItems,
  ListboxSeparator as UiListboxSeparator,
  type ListboxProps as UiListboxProps,
} from '@ui-sdk/solid/listbox'
import { omit } from 'solid-js'

import './listbox.css'

export type ListboxSurface = 'base' | 'layer-1'

export type ListboxProps<
  T = string,
  Multiple extends boolean | undefined = false,
> = UiListboxProps<T, Multiple> & {
  /** Background surface fill. Defaults to `base`. */
  surface?: ListboxSurface
  /** Marks the container outline red. */
  invalid?: boolean
}

export function Listbox<
  T = string,
  Multiple extends boolean | undefined = false,
>(props: ListboxProps<T, Multiple>) {
  const rest = omit(
    props as Record<string, unknown>,
    'surface',
    'invalid',
  ) as UiListboxProps<T, Multiple>

  return (
    <UiListbox<T, Multiple>
      {...rest}
      data-surface={props.surface ?? 'base'}
      data-invalid={props.invalid ? '' : undefined}
    />
  )
}

type BaseListboxItemProps = ComponentProps<typeof UiListboxItem>

export type ListboxItemProps<T = string> = Omit<
  BaseListboxItemProps,
  'value' | 'class' | 'render'
> & {
  value: T
  class?: BaseListboxItemProps['class']
  render?: BaseListboxItemProps['render']
}

export function ListboxItem<T = string>(props: ListboxItemProps<T>) {
  const rest = omit(props, 'value', 'class', 'render')

  return (
    <UiListboxItem<T>
      {...rest}
      value={props.value}
      class={props.class}
      render={props.render}
    />
  )
}

type UiListboxItemIndicatorProps = ComponentProps<typeof UiListboxItemIndicator>

export type ListboxItemIndicatorProps = Omit<
  UiListboxItemIndicatorProps,
  'class' | 'render' | 'children'
> & {
  class?: UiListboxItemIndicatorProps['class']
  render?: UiListboxItemIndicatorProps['render']
  children?: UiListboxItemIndicatorProps['children']
}

export function ListboxItemIndicator(props: ListboxItemIndicatorProps) {
  const rest = omit(props, 'class', 'render', 'children')

  return (
    <UiListboxItemIndicator
      {...rest}
      class={props.class}
      render={props.render}
    >
      {(state) =>
        typeof props.children === 'function'
          ? props.children(state)
          : (props.children ?? <CheckMark />)
      }
    </UiListboxItemIndicator>
  )
}

type UiListboxItemIconProps = ComponentProps<typeof UiListboxItemIcon>

export type ListboxItemIconProps = Omit<
  UiListboxItemIconProps,
  'class' | 'render'
> & {
  class?: UiListboxItemIconProps['class']
  render?: UiListboxItemIconProps['render']
}

export function ListboxItemIcon(props: ListboxItemIconProps) {
  const rest = omit(props, 'class', 'render')

  return (
    <UiListboxItemIcon {...rest} class={props.class} render={props.render} />
  )
}

type UiListboxGroupProps = ComponentProps<typeof UiListboxGroup>

export type ListboxGroupProps = Omit<
  UiListboxGroupProps,
  'class' | 'render'
> & {
  class?: UiListboxGroupProps['class']
  render?: UiListboxGroupProps['render']
}

export function ListboxGroup(props: ListboxGroupProps) {
  const rest = omit(props, 'class', 'render')

  return <UiListboxGroup {...rest} class={props.class} render={props.render} />
}

type UiListboxGroupLabelProps = ComponentProps<typeof UiListboxGroupLabel>

export type ListboxGroupLabelProps = Omit<
  UiListboxGroupLabelProps,
  'class' | 'render'
> & {
  class?: UiListboxGroupLabelProps['class']
  render?: UiListboxGroupLabelProps['render']
}

export function ListboxGroupLabel(props: ListboxGroupLabelProps) {
  const rest = omit(props, 'class', 'render')

  return (
    <UiListboxGroupLabel {...rest} class={props.class} render={props.render} />
  )
}

type UiListboxSeparatorProps = ComponentProps<typeof UiListboxSeparator>

export type ListboxSeparatorProps = Omit<
  UiListboxSeparatorProps,
  'class' | 'render'
> & {
  class?: UiListboxSeparatorProps['class']
  render?: UiListboxSeparatorProps['render']
}

export function ListboxSeparator(props: ListboxSeparatorProps) {
  const rest = omit(props, 'class', 'render')

  return (
    <UiListboxSeparator {...rest} class={props.class} render={props.render} />
  )
}

export { createListboxController, ListboxItems }

function CheckMark(): JSX.Element {
  return (
    <svg
      width="14"
      height="14"
      viewBox="0 0 16 16"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      aria-hidden="true"
    >
      <path
        d="M3.53564 8.17857L6.39279 11.75L12.4642 4.25"
        stroke="currentColor"
        stroke-width="1.2"
        stroke-linecap="round"
        stroke-linejoin="round"
      />
    </svg>
  )
}

@layer components {
  /* ---------------------------------------------------------------- */
  /* Listbox container                                                */
  /* ---------------------------------------------------------------- */

  [data-slot="listbox"] {
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    align-items: stretch;
    gap: 2px;
    width: 280px;
    max-width: 100%;
    margin: 0;
    padding: 4px;
    border: 0;
    border-radius: 8px;
    outline: 1px solid transparent;
    outline-offset: -1px;
    background: var(--v2-background-bg-base);
    box-shadow: var(--v2-elevation-input);
    overflow-y: auto;
    overflow-x: hidden;
    transition:
      outline-color 85ms ease-out,
      box-shadow 85ms ease-out;

    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    text-rendering: geometricPrecision;
  }

  [data-slot="listbox"][data-surface="layer-1"] {
    background: var(--v2-background-bg-layer-01);
  }

  [data-slot="listbox"]:focus-visible {
    outline: 2px solid var(--v2-border-border-focus);
    outline-offset: 2px;
  }

  [data-slot="listbox"][data-invalid]:not([data-disabled]) {
    outline-color: var(--v2-state-fg-danger);
    box-shadow: none;
  }

  [data-slot="listbox"][data-disabled] {
    opacity: 0.5;
    cursor: not-allowed;
  }

  [data-slot="listbox"][data-orientation="horizontal"] {
    flex-direction: row;
    flex-wrap: wrap;
    align-items: center;
    width: fit-content;
    gap: 4px;
  }

  /* ---------------------------------------------------------------- */
  /* Items (matches select.css item rows)                             */
  /* ---------------------------------------------------------------- */

  [data-slot="listbox-item"] {
    box-sizing: border-box;
    display: flex;
    flex-shrink: 0;
    flex-direction: row;
    align-items: center;
    gap: 8px;
    min-height: 28px;
    padding: 4px 8px;
    background: transparent;
    border-radius: 4px;
    outline: none;
    cursor: default;
    user-select: none;
    text-decoration: none;

    font-size: 13px;
    font-weight: 440;
    line-height: var(--line-height-compact);
    letter-spacing: -0.04px;
    font-variation-settings: "slnt" 0;
    font-variant-numeric: tabular-nums;
    color: var(--v2-text-text-base);
    transition: background 85ms ease-out;
  }

  [data-slot="listbox"][data-orientation="horizontal"] [data-slot="listbox-item"] {
    padding: 4px 10px;
    justify-content: center;
  }

  @media (hover: hover) {
    [data-slot="listbox-item"]:hover:not([data-disabled]) {
      background: var(--v2-overlay-simple-overlay-hover);
    }
  }

  [data-slot="listbox-item"][data-selected] {
    background: var(--v2-overlay-simple-overlay-hover);
    font-weight: 530;
  }

  [data-slot="listbox-item"][data-highlighted] {
    background: var(--v2-overlay-simple-overlay-hover);
  }

  [data-slot="listbox-item"][data-selected][data-highlighted] {
    background: var(--v2-overlay-simple-overlay-pressed);
  }

  [data-slot="listbox-item"]:focus-visible {
    outline: 2px solid var(--v2-border-border-focus);
    outline-offset: -2px;
  }

  [data-slot="listbox"]:focus-visible [data-slot="listbox-item"][data-highlighted] {
    outline: 1px solid var(--v2-border-border-focus);
    outline-offset: -1px;
  }

  [data-slot="listbox-item"][data-disabled] {
    pointer-events: none;
    opacity: 0.5;
  }

  [data-slot="listbox-item-icon"] {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex: none;
    width: 16px;
    height: 16px;
    color: var(--v2-icon-icon-muted);
  }

  [data-slot="listbox-item"]:is([data-highlighted], [data-selected])
    [data-slot="listbox-item-icon"] {
    color: var(--v2-icon-icon-base);
  }

  [data-slot="listbox-item-icon"] svg {
    display: block;
    width: 14px;
    height: 14px;
  }

  :dir(rtl) [data-slot="listbox-item-icon"][data-mirror] {
    transform: scaleX(-1);
  }

  [data-slot="listbox-item-indicator"] {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex: none;
    width: 16px;
    height: 16px;
    margin-inline-start: auto;
    color: var(--v2-icon-icon-base);
  }

  [data-slot="listbox-item-indicator"]:not([data-selected]) > svg {
    visibility: hidden;
  }

  /* ---------------------------------------------------------------- */
  /* Groups & separators                                              */
  /* ---------------------------------------------------------------- */

  [data-slot="listbox-group"] {
    display: flex;
    flex-direction: column;
    align-items: stretch;
    gap: 2px;
  }

  [data-slot="listbox-group-label"] {
    box-sizing: border-box;
    display: flex;
    align-items: center;
    height: 24px;
    padding: 0 8px;
    font-size: 11px;
    font-weight: 530;
    letter-spacing: 0.05px;
    color: var(--v2-text-text-faint);
    user-select: none;
    font-variant-numeric: tabular-nums;
  }

  [data-slot="listbox-separator"] {
    flex: none;
    height: 1px;
    width: calc(100% + 4px);
    margin: 3px -2px;
    background: var(--v2-border-border-muted);
    border: none;
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="listbox"],
    [data-slot="listbox-item"] {
      transition: none;
    }
  }
}
